const __helpers = this.helpers;
async function _http(o) {
  const opts = {
    method: o.method || 'GET',
    url: o.url,
    headers: o.headers || {},
    timeout: o.timeout || 30000,
  };
  if (o.body !== undefined) opts.body = o.body;
  if (o.responseFormat === 'json' || typeof o.body === 'object') opts.json = true;
  return await __helpers.httpRequest(opts);
}

let __cfg = {};
try { __cfg = $input.first()?.json || {}; } catch (_) {}
const getVar = (name) => {
  try { if ($vars && $vars[name]) return $vars[name]; } catch (_) {}
  return __cfg[name] || '';
};
const SUPABASE_URL = getVar('SUPABASE_URL').replace(/\/$/, '');
const SERVICE_KEY = getVar('SUPABASE_SERVICE_ROLE_KEY');
const SITE_URL = getVar('NEXT_PUBLIC_SITE_URL').replace(/\/$/, '');
const REVALIDATE_SECRET = getVar('REVALIDATE_SECRET');

if (!SUPABASE_URL || !SERVICE_KEY) {
  throw new Error('Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY in n8n Variables');
}

const supabaseHeaders = (extra = {}) => ({
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
  ...extra,
});

async function supabase(path, method = 'GET', body, extra = {}) {
  const options = {
    method,
    url: `${SUPABASE_URL}/rest/v1/${path}`,
    headers: supabaseHeaders(extra.headers || {}),
    timeout: 30000,
    responseFormat: extra.responseFormat || 'json',
  };
  if (body !== undefined) options.body = body;
  return await _http(options);
}

async function logStep(articleId, sourceId, step, status, message, metadata = {}) {
  try {
    await supabase('processing_logs', 'POST', {
      article_id: articleId || null,
      source_id: sourceId || null,
      step,
      status,
      message: String(message || '').slice(0, 2000),
      metadata,
    }, { headers: { Prefer: 'return=minimal' }, responseFormat: 'text' });
  } catch (_) {}
}

function cleanText(text, max = 6000) {
  return String(text || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

function stableHash(value) {
  return Buffer.from(String(value || '')).toString('base64url').slice(0, 120);
}

function decodeXml(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .trim();
}

function xmlTag(xml, names) {
  for (const name of names) {
    const match = xml.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)<\\/${name}>`, 'i'));
    if (match) return decodeXml(match[1]);
  }
  return '';
}

function xmlLink(item) {
  const href = item.match(/<link[^>]+href=["']([^"']+)["'][^>]*>/i)?.[1];
  return decodeXml(href || xmlTag(item, ['link', 'guid']));
}

function slugify(value, fallback) {
  const slug = String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 65);
  return slug || fallback;
}


const YOUTUBE_KEY = getVar('YOUTUBE_DATA_API_KEY');
if (!YOUTUBE_KEY) throw new Error('Missing YOUTUBE_DATA_API_KEY in n8n Variables');

async function ytJson(url) {
  return await _http({ method: 'GET', url, responseFormat: 'json', timeout: 25000 });
}

async function channelIdFor(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/(?:channel\/|@)([A-Za-z0-9_.-]+)/);
  const candidate = match ? match[1] : raw;
  if (/^UC[A-Za-z0-9_-]{22}$/.test(candidate)) return candidate;
  const handle = candidate.replace(/^@/, '');
  const res = await ytJson(`https://www.googleapis.com/youtube/v3/channels?part=id&forHandle=${encodeURIComponent(handle)}&key=${encodeURIComponent(YOUTUBE_KEY)}`);
  if (!res.items?.length) throw new Error(`Could not resolve YouTube channel: ${value}`);
  return res.items[0].id;
}

const sources = await supabase('sources?select=id,name,url,language,category_id,categories(is_active)&source_type=eq.youtube&is_active=eq.true');
const results = [];

for (const source of sources || []) {
  if (source.categories && source.categories.is_active === false) {
    results.push({ source: source.name, skipped: 'category inactive' });
    continue;
  }
  let found = 0;
  let inserted = 0;
  try {
    const channelId = await channelIdFor(source.url);
    const search = await ytJson(`https://www.googleapis.com/youtube/v3/search?part=snippet&channelId=${encodeURIComponent(channelId)}&maxResults=15&order=date&type=video&key=${encodeURIComponent(YOUTUBE_KEY)}`);

    for (const video of search.items || []) {
      const videoId = video.id?.videoId;
      const snippet = video.snippet || {};
      if (!videoId || !snippet.title) continue;
      found++;

      const existing = await supabase(`articles?select=id&content_hash=eq.${encodeURIComponent(videoId)}&limit=1`);
      if (existing?.length) continue;

      const videoUrl = `https://www.youtube.com/watch?v=${videoId}`;
      const rows = await supabase('articles', 'POST', [{
        source_id: source.id,
        source_url: videoUrl,
        canonical_url: videoUrl,
        content_hash: videoId,
        source_type: 'video',
        original_language: source.language || 'en',
        category_id: source.category_id,
        published_date: snippet.publishedAt || null,
        author: snippet.channelTitle || source.name,
        featured_image_url: snippet.thumbnails?.high?.url || snippet.thumbnails?.medium?.url || snippet.thumbnails?.default?.url || null,
        status: 'pending',
        raw_metadata: {
          title: snippet.title,
          description: snippet.description || '',
          channel_title: snippet.channelTitle,
          youtube_video_id: videoId,
        },
      }], { headers: { Prefer: 'return=representation' } });

      inserted++;
      await logStep(rows?.[0]?.id, source.id, 'fetch', 'success', 'YouTube video ingested', { video_id: videoId });
    }

    await supabase(`sources?id=eq.${source.id}`, 'PATCH', { last_checked_at: new Date().toISOString(), last_error: null }, { headers: { Prefer: 'return=minimal' }, responseFormat: 'text' });
    results.push({ source: source.name, found, inserted });
  } catch (error) {
    await supabase(`sources?id=eq.${source.id}`, 'PATCH', { last_checked_at: new Date().toISOString(), last_error: error.message }, { headers: { Prefer: 'return=minimal' }, responseFormat: 'text' });
    await logStep(null, source.id, 'fetch', 'error', error.message, { source_url: source.url });
    results.push({ source: source.name, error: error.message });
  }
}

return [{ json: { ok: true, results } }];
